static void ath9k_hif_usb_reboot ( struct usb_device * udev ) { u32 reboot_cmd = 0xffffffff ; void * buf ; int ret ; buf = kmemdup ( & reboot_cmd , 4 , GFP_KERNEL ) ; ret = usb_interrupt_msg ( udev , usb_sndintpipe ( udev , USB_REG_OUT_PIPE ) , buf , 4 , NULL , USB_MSG_TIMEOUT ) ; if ( ret ) { dev_err ( & udev -> dev , "ath9k_htc: USB reboot failed\n" ) ; } kfree ( buf ) ; } 